namespace MaintenancePRO.Views; public partial class PageHeader:ContentView { public PageHeader(){InitializeComponent(); TitleLabel.Text=Heading; SubtitleLabel.Text=Subtitle;} public static readonly BindableProperty HeadingProperty=BindableProperty.Create(nameof(Heading),typeof(string),typeof(PageHeader),"Titre",propertyChanged:(b,o,n)=>((PageHeader)b).TitleLabel.Text=(string)n); public static readonly BindableProperty SubtitleProperty=BindableProperty.Create(nameof(Subtitle),typeof(string),typeof(PageHeader),"",propertyChanged:(b,o,n)=>((PageHeader)b).SubtitleLabel.Text=(string)n); public string Heading{get=>(string)GetValue(HeadingProperty);set=>SetValue(HeadingProperty,value);} public string Subtitle{get=>(string)GetValue(SubtitleProperty);set=>SetValue(SubtitleProperty,value);} }